vec4 fx(vec2 uv){ vec4 b=inp(uv); float m=gradRamp(uv,P3,P4,P5)*P2; vec3 t=hueCol(P0,P1); vec3 o; if(P6<.5) o=mix(b.rgb,b.rgb*0.35+t*luma709(b.rgb)*0.9,m); else if(P6<1.5) o=mix(b.rgb,b.rgb*t,m); else if(P6<2.5) o=mix(b.rgb,b.rgb+t-b.rgb*t,m); else { vec3 ov=mix(2.0*b.rgb*t,1.0-2.0*(1.0-b.rgb)*(1.0-t),step(0.5,b.rgb)); o=mix(b.rgb,ov,m); } return vec4(clamp(o,0.0,1.0),b.a); }

