float gradRamp(vec2 uv, float angDeg, float c, float w){ float a=radians(angDeg); vec2 d=vec2(cos(a),sin(a)); float t=dot(uv-0.5,d)+0.5; return smoothstep(c-w*0.5, c+w*0.5, t); }
