vec4 fx(vec2 uv){ vec4 b=inp(uv); float l=luma709(b.rgb); float t=smoothstep(0.0,1.0,clamp(l+P4*0.5,0.0,1.0)); vec3 sh=hueCol(P0,1.0), hi=hueCol(P2,1.0); vec3 tint=mix(sh,vec3(1.0),1.0-P1*(1.0-t))*mix(hi,vec3(1.0),1.0-P3*t); vec3 o=b.rgb*tint; float l2=luma709(o); o*=mix(1.0,l/max(l2,1e-4),P5); return vec4(clamp(o,0.0,1.0),b.a); }

