vec4 fx(vec2 uv){ vec4 b=inp(uv); float y=(P1-uv.y)/max(P3,1e-3); vec3 top=vec3(.35,.2,.55), mid=vec3(1.0,.45,.15), low=vec3(1.0,.8,.35); mid=mix(mid,vec3(1.0,.25,.05),P2*0.5); vec3 sky=y>0.5?mix(mid,top,smoothstep(0.5,1.5,y)):mix(low,mid,smoothstep(-0.2,0.5,y)); float m=smoothstep(-0.35,0.15,y)*P0; vec3 o=mix(b.rgb,b.rgb*sky*1.25+sky*0.1,m); return vec4(clamp(o,0.0,1.0),b.a); }

