float fh(vec2 p){ return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453); } vec4 fx(vec2 uv){ vec4 b=inp(uv); vec2 cell=floor(uv*uResolution/P2); vec2 j=vec2(fh(cell),fh(cell+7.7))-0.5; vec3 s=inp(uv+j*P1/uResolution).rgb; vec3 acc=vec3(0.0); for(int k=0;k<6;k++){ float a=float(k)*1.047; vec2 o=vec2(cos(a),sin(a))*P1/uResolution*(0.4+0.6*fh(cell+float(k))); acc+=inp(uv+o).rgb; } acc/=6.0; vec3 soft=mix(acc,s,0.4); float l=luma709(soft); float sp=smoothstep(.6,.95,l)*fh(cell*1.3)*P3; vec3 o=mix(b.rgb,soft,P0)+sp*0.5; return vec4(clamp(o,0.0,1.0),b.a); }

